import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 29 Taxi!","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 29 Taxi!","description":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 现在完成时与过去时间，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 28 No parking","link":"/life/english/new-concept/book-2/unit-02/lesson-028"},"next":{"text":"第二册：实践与进步 · Lesson 30 Football or polo?","link":"/life/english/new-concept/book-2/unit-02/lesson-030"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 28 No parking","link":"/life/english/new-concept/book-2/unit-02/lesson-028"},"next":{"text":"第二册：实践与进步 · Lesson 30 Football or polo?","link":"/life/english/new-concept/book-2/unit-02/lesson-030"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-029.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-029.md"}'),i={name:"life/english/new-concept/book-2/unit-02/lesson-029.md"};function l(r,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-29-taxi" tabindex="-1">第二册：实践与进步 · Lesson 29 Taxi! <a class="header-anchor" href="#第二册-实践与进步-·-lesson-29-taxi" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 29 Taxi!&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>交通服务不一定只在公路上进行，短途飞行也要看天气与场地；练习截至现在的服务记录。本课的语言观察是：has carried 统计到当前的乘客数量；a hundred passengers 不表示一次飞行装载一百人，应根据时间范围理解累计。完成学习后，请介绍一个特别的交通服务，写累计成果、今天情况与下一步安排。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>passenger</td><td>/ˈpæsɪndʒə/</td><td>n.</td><td>乘客</td><td>a train passenger</td></tr><tr><td>land</td><td>/lænd/</td><td>v.</td><td>着陆</td><td>land safely</td></tr><tr><td>flight</td><td>/flaɪt/</td><td>n.</td><td>飞行；航班</td><td>a short flight</td></tr><tr><td>roof</td><td>/ruːf/</td><td>n.</td><td>屋顶</td><td>a flat roof</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take off — 起飞，也可表示脱下，要看语境</li><li>land on — 在某表面着陆</li></ul><h2 id="语法讲解-现在完成时与过去时间" tabindex="-1">语法讲解：现在完成时与过去时间 <a class="header-anchor" href="#语法讲解-现在完成时与过去时间" aria-label="Permalink to &quot;语法讲解：现在完成时与过去时间&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has carried 统计到当前的乘客数量；a hundred passengers 不表示一次飞行装载一百人，应根据时间范围理解累计。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The small plane has carried a hundred passengers this week.</p></blockquote><p>这架小飞机本周已运送一百名乘客。</p><p>has carried 是现在完成时，a hundred passengers 为累计宾语，this week 连接过去活动与现在。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>has flew 错误，fly 的过去分词是 flown；本例 carry 的过去分词是 carried。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>比较 carried 和 cancelled 的词尾，重读 a hundred 与 this week 表数量范围。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The small plane has carried a hundred passengers this week. Today the wind is too strong. The pilot has cancelled the afternoon flights.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>介绍一个特别的交通服务，写累计成果、今天情况与下一步安排。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：has carried 是现在完成时，a hundred passengers 为累计宾语，this week 连接过去活动与现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：has flew 错误，fly 的过去分词是 flown；本例 carry 的过去分词是 carried。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 carry 的过去分词：The plane has ___ many passengers.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> carried</p><p><strong>解析：</strong> 辅音字母加 y 结尾变 y 为 i 再加 -ed。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>今天下午航班为什么取消？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Because the wind is too strong.</p><p><strong>解析：</strong> 取消是基于当前天气，不是载客量过大。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填 fly：The pilot has ___ this route before.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> flown</p><p><strong>解析：</strong> fly 的过去分词是不规则形式 flown。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在完成时与过去时间。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-028">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-030">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
